// nonleaf_proc runs the nonleaf_proc Golang process.
//
// nonleaf_proc is auto-generated by Blueprint's goproc plugin (goproc/goprocgen/main.go.go)
//
// Usage:
//
//   go run main.go --leaf_service.http.dial_addr=value --zipkin.dial_addr=value --nonleaf_service.http.bind_addr=value 
//
// Optional env: GC_INTERVAL_SEC=N (e.g. 30, 1, 0.5, 0.1) to run GC every N seconds; fractional seconds supported. Omit or <=0 for default GC.
//
// nonleaf_proc requires the following arguments are passed:
//
//   --leaf_service.http.dial_addr
//       Auto-generated by Blueprint IR node:
//       leaf_service.http.dial_addr = AddressConfig()
//
//   --zipkin.dial_addr
//       Auto-generated by Blueprint IR node:
//       zipkin.dial_addr = AddressConfig()
//
//   --nonleaf_service.http.bind_addr
//       Auto-generated by Blueprint IR node:
//       nonleaf_service.http.bind_addr = AddressConfig()
//
// nonleaf_proc will instantiate the following IR nodes:
//   nonleaf_proc.stdoutmetriccollector
//   nonleaf_proc.logger
//   leaf_service.http_client
//   zipkin.client
//   leaf_service.client.ot
//   leaf_service.client
//   nonleaf_service
//   nonleaf_service.server.ot
//   nonleaf_service.http_server
package main

import (
	"context"
	"os"
	"runtime"
	"strconv"
	"time"

	"log/slog"
)

func main() {
	// Optional: run GC on a fixed interval to normalize GC frequency (e.g. across tracing vs no-tracing).
	// Set GC_INTERVAL_SEC to a positive number (e.g. 30, 1, 0.5, 0.1) to trigger runtime.GC() every N seconds; unset or <=0 to leave default GC behavior.
	if sec := os.Getenv("GC_INTERVAL_SEC"); sec != "" {
		if secVal, err := strconv.ParseFloat(sec, 64); err == nil && secVal > 0 && secVal < 1e15 {
			interval := time.Duration(secVal * float64(time.Second))
			if interval > 0 {
				go func() {
					ticker := time.NewTicker(interval)
					defer ticker.Stop()
					for range ticker.C {
						runtime.GC()
					}
				}()
			}
		}
	}
	slog.Info("Running nonleaf_proc")
	n, err := New_nonleaf_proc("nonleaf_proc").Build(context.Background())
	if err != nil {
		slog.Error(err.Error())
		os.Exit(1)
	}
	n.Await()
	slog.Info("nonleaf_proc exiting")
}